import java.io.*;
import java.util.*;

public class Main {
    static class Matrix {
        long[][] a;
        Matrix() {
            a = new long[3][3];
        }
    }

    static long n;

    static long modMul(long a, long b) {
        a %= n;
        b %= n;
        long res = 0;
        while (b > 0) {
            if ((b & 1) != 0) {
                res += a;
                if (res >= n) res -= n;
            }
            a <<= 1;
            if (a >= n) a -= n;
            b >>= 1;
        }
        return res;
    }

    static Matrix mul(Matrix x, Matrix y) {
        Matrix r = new Matrix();
        for (int i = 0; i < 3; i++) {
            for (int k = 0; k < 3; k++) {
                if (x.a[i][k] == 0) continue;
                for (int j = 0; j < 3; j++) {
                    if (y.a[k][j] == 0) continue;
                    long val = modMul(x.a[i][k], y.a[k][j]);
                    r.a[i][j] += val;
                    r.a[i][j] %= n;
                }
            }
        }
        return r;
    }

    static Matrix pow(Matrix base, long exp) {
        Matrix res = new Matrix();
        for (int i = 0; i < 3; i++) res.a[i][i] = 1 % n;
        while (exp > 0) {
            if ((exp & 1) != 0) res = mul(res, base);
            base = mul(base, base);
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Long.parseLong(st.nextToken());
        long sx = Long.parseLong(st.nextToken());
        long sy = Long.parseLong(st.nextToken());
        long dx = Long.parseLong(st.nextToken());
        long dy = Long.parseLong(st.nextToken());
        long t = Long.parseLong(st.nextToken());

        dx %= n;
        dy %= n;
        if (dx < 0) dx += n;
        if (dy < 0) dy += n;

        if (t == 0) {
            System.out.println(sx + " " + sy);
            return;
        }

        long s = (sx + sy) % n;

        Matrix M = new Matrix();
        // Row 0: s'
        M.a[0][0] = 1 % n;
        M.a[0][1] = 2 % n;
        M.a[0][2] = 1 % n;
        // Row 1: dx'
        M.a[1][0] = 1 % n;
        M.a[1][1] = 1 % n;
        M.a[1][2] = 0;
        // Row 2: dy'
        M.a[2][0] = 1 % n;
        M.a[2][1] = 0;
        M.a[2][2] = 1 % n;

        Matrix Mt = pow(M, t);

        long[] v = new long[3];
        v[0] = s % n;
        v[1] = dx;
        v[2] = dy;

        long[] res = new long[3];
        for (int i = 0; i < 3; i++) {
            long val = 0;
            for (int j = 0; j < 3; j++) {
                if (Mt.a[i][j] == 0) continue;
                val += modMul(Mt.a[i][j], v[j]);
                val %= n;
            }
            res[i] = val;
        }

        long sT = res[0];
        long dxT = res[1];
        long dyT = res[2];

        long x = (sT - dyT) % n;
        if (x < 0) x += n;
        long y = (sT - dxT) % n;
        if (y < 0) y += n;

        long finalX = ((x + n - 1) % n) + 1;
        long finalY = ((y + n - 1) % n) + 1;

        System.out.println(finalX + " " + finalY);
    }
}

