public class Main {
    // Multiply 2x2 matrix with vector (size 2)
    static long[] mulMatVec(long[][] m, long[] v, long mod) {
        long[] res = new long[2];
        res[0] = ( (m[0][0] * v[0]) % mod + (m[0][1] * v[1]) % mod ) % mod;
        res[1] = ( (m[1][0] * v[0]) % mod + (m[1][1] * v[1]) % mod ) % mod;
        return res;
    }

    // Multiply 2x2 matrices
    static long[][] mulMat(long[][] a, long[][] b, long mod) {
        long[][] r = new long[2][2];
        r[0][0] = ( (a[0][0] * b[0][0]) % mod + (a[0][1] * b[1][0]) % mod ) % mod;
        r[0][1] = ( (a[0][0] * b[0][1]) % mod + (a[0][1] * b[1][1]) % mod ) % mod;
        r[1][0] = ( (a[1][0] * b[0][0]) % mod + (a[1][1] * b[1][0]) % mod ) % mod;
        r[1][1] = ( (a[1][0] * b[0][1]) % mod + (a[1][1] * b[1][1]) % mod ) % mod;
        return r;
    }

    // Fast exponentiation of 2x2 matrix
    static long[][] powMat(long[][] base, long exp, long mod) {
        long[][] res = new long[2][2];
        res[0][0] = 1; res[0][1] = 0;
        res[1][0] = 0; res[1][1] = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) res = mulMat(res, base, mod);
            base = mulMat(base, base, mod);
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long sx = Long.parseLong(st.nextToken());
        long sy = Long.parseLong(st.nextToken());
        long dx = Long.parseLong(st.nextToken());
        long dy = Long.parseLong(st.nextToken());
        long t = Long.parseLong(st.nextToken());

        if (t == 0) {
            System.out.println(sx + " " + sy);
            return;
        }

        long mod = n;

        // Initial k0 = sx + sy
        long k0 = sx + sy;

        // Matrix A for k: [k_{i+1}] = [3 2; 1 1] * [k_i; 1]
        long[][] A = new long[2][2];
        A[0][0] = 3 % mod; A[0][1] = 2 % mod;
        A[1][0] = 1 % mod; A[1][1] = 1 % mod;

        // Compute A^t
        long[][] At = powMat(A, t, mod);

        // Vector [k0; 1]
        long[] v0 = new long[2];
        v0[0] = ((k0 % mod) + mod) % mod;
        v0[1] = 1 % mod;

        long[] vt = mulMatVec(At, v0, mod);
        long kt = vt[0]; // k_t modulo n

        // dx_t = dx + (k_t - k0)
        long dx_t = dx + (kt - (k0 % mod));
        long dy_t = dy + (kt - (k0 % mod));

        long x = ((sx + dx_t - 1) % n + n) % n + 1;
        long y = ((sy + dy_t - 1) % n + n) % n + 1;

        System.out.println(x + " " + y);
    }
}

