public class Main {
    static class Mat {
        long a, b, c, d; // 2x2 matrix

        Mat(long a, long b, long c, long d) {
            this.a = a; this.b = b; this.c = c; this.d = d;
        }

        Mat mul(Mat o, long mod) {
            long na = (a * o.a + b * o.c) % mod;
            long nb = (a * o.b + b * o.d) % mod;
            long nc = (c * o.a + d * o.c) % mod;
            long nd = (c * o.b + d * o.d) % mod;
            return new Mat(na, nb, nc, nd);
        }
    }

    static Mat matPow(Mat base, long exp, long mod) {
        Mat res = new Mat(1, 0, 0, 1); // identity
        while (exp > 0) {
            if ((exp & 1) != 0) res = res.mul(base, mod);
            base = base.mul(base, mod);
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        long sx = fs.nextLong();
        long sy = fs.nextLong();
        long dx = fs.nextLong();
        long dy = fs.nextLong();
        long t = fs.nextLong();

        long mod = 2 * n;

        long x0 = ((sx - 1) * 2) % mod;
        long y0 = ((sy - 1) * 2) % mod;

        long dx0 = ((dx % mod) + mod) % mod;
        long dy0 = ((dy % mod) + mod) % mod;

        long k0 = ((sx + sy) % mod + mod) % mod;

        long tmod = t % mod;

        Mat A = new Mat(1, 1, 0, 1);
        Mat Aexp = matPow(A, tmod, mod);

        long dxT = (Aexp.a * dx0 + Aexp.b * k0) % mod;
        long dyT = (Aexp.a * dy0 + Aexp.b * k0) % mod;

        long xT = (x0 + dxT) % mod;
        long yT = (y0 + dyT) % mod;

        long finalX = xT / 2 + 1;
        long finalY = yT / 2 + 1;

        System.out.println(finalX + " " + finalY);
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

