public class Main {
    static class Mat {
        long a00, a01, a02;
        long a10, a11, a12;
        long a20, a21, a22;
        long mod;

        Mat(long mod) {
            this.mod = mod;
        }

        static Mat identity(long mod) {
            Mat m = new Mat(mod);
            m.a00 = m.a11 = m.a22 = 1 % mod;
            return m;
        }

        Mat mul(Mat o) {
            Mat r = new Mat(mod);
            r.a00 = (a00 * o.a00 + a01 * o.a10 + a02 * o.a20) % mod;
            r.a01 = (a00 * o.a01 + a01 * o.a11 + a02 * o.a21) % mod;
            r.a02 = (a00 * o.a02 + a01 * o.a12 + a02 * o.a22) % mod;

            r.a10 = (a10 * o.a00 + a11 * o.a10 + a12 * o.a20) % mod;
            r.a11 = (a10 * o.a01 + a11 * o.a11 + a12 * o.a21) % mod;
            r.a12 = (a10 * o.a02 + a11 * o.a12 + a12 * o.a22) % mod;

            r.a20 = (a20 * o.a00 + a21 * o.a10 + a22 * o.a20) % mod;
            r.a21 = (a20 * o.a01 + a21 * o.a11 + a22 * o.a21) % mod;
            r.a22 = (a20 * o.a02 + a21 * o.a12 + a22 * o.a22) % mod;
            return r;
        }

        long[] apply(long[] v) {
            long[] r = new long[3];
            r[0] = (a00 * v[0] + a01 * v[1] + a02 * v[2]) % mod;
            r[1] = (a10 * v[0] + a11 * v[1] + a12 * v[2]) % mod;
            r[2] = (a20 * v[0] + a21 * v[1] + a22 * v[2]) % mod;
            return r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        long sx = fs.nextLong();
        long sy = fs.nextLong();
        long dx = fs.nextLong();
        long dy = fs.nextLong();
        long t = fs.nextLong();

        if (t == 0) {
            System.out.println(sx + " " + sy);
            return;
        }

        long mod = n;
        long x0 = ((sx - 1) % mod + mod) % mod;
        long y0 = ((sy - 1) % mod + mod) % mod;
        long dx0 = ((dx % mod) + mod) % mod;
        long dy0 = ((dy % mod) + mod) % mod;

        Mat base = new Mat(mod);
        base.a00 = 1; base.a01 = 0; base.a02 = 1;
        base.a10 = 0; base.a11 = 1; base.a12 = 1;
        base.a20 = 2; base.a21 = 2; base.a22 = 3;

        Mat cur = Mat.identity(mod);
        Mat pow = base;
        long steps = t;
        while (steps > 0) {
            if ((steps & 1) != 0) cur = cur.mul(pow);
            pow = pow.mul(pow);
            steps >>= 1;
        }

        long[] v = new long[]{dx0, dy0, (x0 + y0) % mod};
        long[] res = cur.apply(v);

        long dxT = res[0];
        long dyT = res[1];
        long sT = res[2];

        long xT = (sT - dyT) % mod;
        long yT = (sT - dxT) % mod;
        if (xT < 0) xT += mod;
        if (yT < 0) yT += mod;

        long ansX = xT + 1;
        long ansY = yT + 1;
        System.out.println(ansX + " " + ansY);
    }

    // Fast scanner
