        dx += k0;
        dy += k0;

        // Build matrix M for state [x; y; k]
        Mat M = new Mat();
        // x'
        M.a[0][0] = 1; M.a[0][1] = 0; M.a[0][2] = 0;
        // y'
        M.a[1][0] = 0; M.a[1][1] = 1; M.a[1][2] = 0;
        // k'
        M.a[2][0] = 1; M.a[2][1] = 1; M.a[2][2] = 1;

        Mat Mt = powMat(M, t - 1);

        long k = Mt.a[2][0] * x + Mt.a[2][1] * y + Mt.a[2][2] * k0;

        long dxFinal = dx + k;
        long dyFinal = dy + k;

        long nx = ((x + dxFinal - 1) % n + n) % n + 1;
        long ny = ((y + dyFinal - 1) % n + n) % n + 1;

        System.out.println(nx + " " + ny);
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Mat {
        long[][] a = new long[3][3];
    }

    static long n;

    static Mat mul(Mat x, Mat y) {
        Mat r = new Mat();
        for (int i = 0; i < 3; i++) {
            for (int k = 0; k < 3; k++) {
                if (x.a[i][k] == 0) continue;
                long v = x.a[i][k];
                for (int j = 0; j < 3; j++) {
                    r.a[i][j] += v * y.a[k][j];
                }
            }
        }
        return r;
    }

    static Mat pow(Mat base, long exp) {
        Mat res = new Mat();
        for (int i = 0; i < 3; i++) res.a[i][i] = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) res = mul(res, base);
            base = mul(base, base);
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Long.parseLong(st.nextToken());
        long sx = Long.parseLong(st.nextToken());
        long sy = Long.parseLong(st.nextToken());
        long dx = Long.parseLong(st.nextToken());
        long dy = Long.parseLong(st.nextToken());
        long t = Long.parseLong(st.nextToken());

        if (t == 0) {
            System.out.println(sx + " " + sy);
            return;
        }

        long k0 = sx + sy;
        long dx0 = dx + k0;
        long dy0 = dy + k0;

        Mat M = new Mat();
        // state: [x; dx; k]
        // x' = x + dx
        // dx' = dx + k
        // k' = k + 2
        M.a[0][0] = 1; M.a[0][1] = 1; M.a[0][2] = 0;
        M.a[1][0] = 0; M.a[1][1] = 1; M.a[1][2] = 1;
        M.a[2][0] = 0; M.a[2][1] = 0; M.a[2][2] = 1;

        Mat Mt = pow(M, t);

        long x0 = sx;
        long kInit = k0;

        long xT = Mt.a[0][0] * x0 + Mt.a[0][1] * dx0 + Mt.a[0][2] * kInit;
        long dxT = Mt.a[1][0] * x0 + Mt.a[1][1] * dx0 + Mt.a[1][2] * kInit;
        long kT = Mt.a[2][0] * x0 + Mt.a[2][1] * dx0 + Mt.a[2][2] * kInit + 2 * t;

        long y0 = sy;
        long dy0_ = dy + k0;
        long yT = Mt.a[0][0] * y0 + Mt.a[0][1] * dy0_ + Mt.a[0][2] * kInit;

        long finalX = ((xT - 1) % n + n) % n + 1;
        long finalY = ((yT - 1) % n + n) % n + 1;

        System.out.println(finalX + " " + finalY);
    }
}
